const item = $('Filter and Match').first().json;
const generated = ($input.first().json?.message?.content || $input.first().json?.choices?.[0]?.message?.content || '').trim().slice(0, 500) || 'Thanks for sharing.';
const now = new Date();
const in1min = new Date(now.getTime() + 60 * 1000);
const scheduled_for = in1min.toISOString().replace(/\.\d{3}Z$/, 'Z');
return [{
  json: {
    ...item,
    generated_comment: generated,
    scheduled_for
  }
}];
